<?php
class NtcrRequestService
{
    private static $transitions=array(
        'gift'=>array('pending'=>array('approved','rejected','cancelled'),'approved'=>array('preparing','cancelled'),'preparing'=>array('shipped'),'shipped'=>array('delivered')),
        'explore'=>array('pending'=>array('scheduled','rejected','cancelled'),'scheduled'=>array('processing','cancelled'),'processing'=>array('completed','review','failed'),'review'=>array('completed','failed')),
        'cash'=>array('pending'=>array('payment_pending','rejected','cancelled'),'payment_pending'=>array('paid')),
    );
    public static function validIban($iban)
    {
        $iban=strtoupper(preg_replace('/\s+/','',(string)$iban));if(!preg_match('/^TR\d{24}$/D',$iban))return false;$r=substr($iban,4).strval(ord('T')-55).strval(ord('R')-55).substr($iban,2,2);$mod=0;for($i=0;$i<strlen($r);$i++)$mod=($mod*10+(int)$r[$i])%97;return $mod===1;
    }
    public static function create($publisher,$type,$payload,$shop)
    {
        if(!in_array($type,array('gift','explore','cash'),true))throw new InvalidArgumentException('Geçersiz talep türü.');$db=Db::getInstance();$db->execute('START TRANSACTION');try{$locked=$db->executeS('SELECT * FROM `'._DB_PREFIX_.'ntcr_publisher` WHERE id_publisher='.(int)$publisher.' AND id_shop='.(int)$shop." AND status='verified' LIMIT 1 FOR UPDATE");$p=$locked?$locked[0]:false;if(!$p)throw new RuntimeException('Doğrulanmış yayıncı bulunamadı.');$points=0;$snap=array();$catalog=null;
            if($type==='cash'){$tl=self::moneyToCents($payload['amount_try']??'');if(!$p['cash_allowed'])throw new RuntimeException('Nakit çekim izniniz yok.');if($tl<10000)throw new RuntimeException('Asgari nakit talebi 100 TL’dir.');$points=$tl*10;if(!self::validIban($payload['iban']??''))throw new RuntimeException('IBAN doğrulanamadı.');$owner=trim((string)($payload['account_owner']??''));if($owner==='')throw new RuntimeException('Hesap sahibi zorunludur.');$snap=array('amount_try'=>number_format($tl/100,2,'.',''),'iban'=>strtoupper(preg_replace('/\s+/','',$payload['iban'])),'account_owner'=>$owner,'rate'=>'1000 points/TRY');}
            else{$locked=$db->executeS('SELECT * FROM `'._DB_PREFIX_.'ntcr_catalog` WHERE id_catalog='.(int)($payload['id_catalog']??0).' AND id_shop='.(int)$shop.' AND type=\''.pSQL($type)."' AND active=1 LIMIT 1 FOR UPDATE");$catalog=$locked?$locked[0]:false;if(!$catalog)throw new RuntimeException('Ödül veya paket kullanılamıyor.');$points=(int)$catalog['points'];$snap=array('id_catalog'=>(int)$catalog['id_catalog'],'name'=>$catalog['name'],'description'=>$catalog['description'],'service_scope'=>$catalog['service_scope'],'points'=>$points);if($type==='gift'){if($catalog['stock']!==null&&(int)$catalog['stock']<1)throw new RuntimeException('Hediye stokta yok.');$snap['delivery']=trim((string)($payload['delivery']??''));if($snap['delivery']==='')throw new RuntimeException('Teslimat bilgisi zorunludur.');}}
            if($type==='explore'){$local=new DateTimeImmutable((string)($payload['scheduled_local']??''),new DateTimeZone('Europe/Istanbul'));$min=(new DateTimeImmutable('now',new DateTimeZone('Europe/Istanbul')))->modify('+'.(int)$catalog['min_notice_hours'].' hours');if($local<$min)throw new RuntimeException('Seçilen zaman minimum ön bildirim süresini karşılamıyor.');$utc=$local->setTimezone(new DateTimeZone('UTC'));$count=(int)$db->getValue("SELECT COUNT(*) FROM `"._DB_PREFIX_."ntcr_explore_job` j INNER JOIN `"._DB_PREFIX_."ntcr_request` r ON r.id_request=j.id_request WHERE r.snapshot_json LIKE '%\"id_catalog\":".(int)$catalog['id_catalog']."%' AND j.scheduled_at_utc='".pSQL($utc->format('Y-m-d H:i:s'))."' AND r.status IN ('pending','scheduled','processing')");if($count>=(int)$catalog['slot_capacity'])throw new RuntimeException('Seçilen zaman dolu.');$snap['scheduled_local']=$local->format('Y-m-d H:i:s');$snap['scheduled_utc']=$utc->format('Y-m-d H:i:s');$snap['terms_accepted']=true;}
            $locked=$db->executeS('SELECT * FROM `'._DB_PREFIX_.'ntcr_wallet` WHERE id_publisher='.(int)$publisher.' LIMIT 1 FOR UPDATE');$wallet=$locked?$locked[0]:false;if(!$wallet||(int)$wallet['available_points']<$points)throw new RuntimeException('Kullanılabilir puan yetersiz.');$now=date('Y-m-d H:i:s');$no='NTCR-'.date('Ym').'-'.strtoupper(substr(bin2hex(random_bytes(5)),0,10));$db->insert('ntcr_request',array('request_no'=>$no,'id_shop'=>$shop,'id_publisher'=>$publisher,'type'=>$type,'status'=>'pending','points'=>$points,'snapshot_json'=>json_encode($snap,JSON_UNESCAPED_UNICODE),'date_add'=>$now,'date_upd'=>$now));$id=(int)$db->Insert_ID();$idem='reserve:'.$id;$db->insert('ntcr_reservation',array('id_request'=>$id,'id_publisher'=>$publisher,'points'=>$points,'status'=>'held','idempotency_key'=>$idem,'date_add'=>$now,'date_upd'=>$now));$db->execute('UPDATE `'._DB_PREFIX_.'ntcr_wallet` SET available_points=available_points-'.(int)$points.',reserved_points=reserved_points+'.(int)$points.',date_upd=NOW() WHERE id_publisher='.(int)$publisher);if($type==='gift'&&$catalog['stock']!==null)$db->execute('UPDATE `'._DB_PREFIX_.'ntcr_catalog` SET stock=stock-1,date_upd=NOW() WHERE id_catalog='.(int)$catalog['id_catalog']);if($type==='explore')$db->insert('ntcr_explore_job',array('id_request'=>$id,'scheduled_at_utc'=>$snap['scheduled_utc'],'status'=>'manual_queue','lock_key'=>'explore:'.$id,'date_upd'=>$now));self::event($db,$id,null,'pending',null,null,null);$db->insert('ntcr_outbox',array('event_key'=>'request-created:'.$id,'type'=>'request_created','recipient'=>pSQL(Configuration::get('NTCR_NOTIFY_EMAIL')),'payload_json'=>json_encode(array('request_no'=>$no,'type'=>$type,'publisher'=>$p['handle'],'points'=>$points),JSON_UNESCAPED_UNICODE),'next_attempt_at'=>$now,'date_add'=>$now));$db->execute('COMMIT');return $no;
        }catch(Exception $e){$db->execute('ROLLBACK');throw $e;}
    }
    public static function transition($id,$to,$employee,$shop,$public='',$private='')
    {
        $db=Db::getInstance();$db->execute('START TRANSACTION');try{$locked=$db->executeS('SELECT * FROM `'._DB_PREFIX_.'ntcr_request` WHERE id_request='.(int)$id.' AND id_shop='.(int)$shop.' LIMIT 1 FOR UPDATE');$r=$locked?$locked[0]:false;if(!$r)throw new RuntimeException('Talep bulunamadı.');$allowed=self::$transitions[$r['type']][$r['status']]??array();if(!in_array($to,$allowed,true))throw new RuntimeException('Bu durum geçişine izin verilmiyor.');$locked=$db->executeS('SELECT * FROM `'._DB_PREFIX_.'ntcr_reservation` WHERE id_request='.(int)$id.' LIMIT 1 FOR UPDATE');$res=$locked?$locked[0]:false;$finalSpend=($r['type']==='gift'&&$to==='approved')||($r['type']==='explore'&&$to==='scheduled')||($r['type']==='cash'&&$to==='paid');$release=in_array($to,array('rejected','cancelled','failed'),true);
            if($finalSpend&&$res['status']==='held'){$db->execute('UPDATE `'._DB_PREFIX_.'ntcr_wallet` SET reserved_points=reserved_points-'.(int)$res['points'].',date_upd=NOW() WHERE id_publisher='.(int)$r['id_publisher']);$db->update('ntcr_reservation',array('status'=>'spent','date_upd'=>date('Y-m-d H:i:s')),'id_request='.(int)$id);self::ledger($db,$r,-(int)$res['points'],'spend','request-spend:'.$id);}
            if($release&&$res['status']==='held'){$db->execute('UPDATE `'._DB_PREFIX_.'ntcr_wallet` SET reserved_points=reserved_points-'.(int)$res['points'].',available_points=available_points+'.(int)$res['points'].',date_upd=NOW() WHERE id_publisher='.(int)$r['id_publisher']);$db->update('ntcr_reservation',array('status'=>'released','date_upd'=>date('Y-m-d H:i:s')),'id_request='.(int)$id);$snap=json_decode($r['snapshot_json'],true);if($r['type']==='gift'&&!empty($snap['id_catalog']))$db->execute('UPDATE `'._DB_PREFIX_.'ntcr_catalog` SET stock=stock+1 WHERE id_catalog='.(int)$snap['id_catalog']);}
            $db->update('ntcr_request',array('status'=>pSQL($to),'public_note'=>pSQL($public,true),'private_note'=>pSQL($private,true),'date_upd'=>date('Y-m-d H:i:s')),'id_request='.(int)$id);self::event($db,$id,$r['status'],$to,$public,$private,$employee);$db->execute('COMMIT');return true;
        }catch(Exception $e){$db->execute('ROLLBACK');throw $e;}
    }
    private static function moneyToCents($v){$v=str_replace(',','.',trim((string)$v));if(!preg_match('/^\d+(?:\.\d{1,2})?$/D',$v))throw new RuntimeException('Geçerli bir TL tutarı girin.');list($l,$k)=array_pad(explode('.',$v,2),2,'');return (int)$l*100+(int)str_pad($k,2,'0');}
    private static function event($db,$id,$from,$to,$public,$private,$employee){$db->insert('ntcr_request_event',array('id_request'=>$id,'from_status'=>$from,'to_status'=>$to,'public_note'=>pSQL((string)$public,true),'private_note'=>pSQL((string)$private,true),'id_employee'=>$employee,'date_add'=>date('Y-m-d H:i:s')));}
    private static function ledger($db,$r,$points,$type,$key){$db->insert('ntcr_ledger',array('id_shop'=>$r['id_shop'],'id_publisher'=>$r['id_publisher'],'type'=>$type,'points'=>$points,'idempotency_key'=>$key,'reference_type'=>'request','reference_id'=>$r['id_request'],'description'=>pSQL($r['request_no'].' talebi'),'date_add'=>date('Y-m-d H:i:s')));}
}
